import { Component, input, output } from '@angular/core';
import { NzMenuModule } from 'ng-zorro-antd/menu';

export interface HrmMenuItem {
  key: string;
  label: string;
  disabled?: boolean;
  children?: HrmMenuItem[];
}

/** hrm-menu — menu điều hướng config-driven (1 cấp submenu), bọc nz-menu. */
@Component({
  selector: 'hrm-menu',
  imports: [NzMenuModule],
  template: `
    <ul nz-menu [nzMode]="mode()" [nzInlineCollapsed]="collapsed()">
      @for (item of items(); track item.key) {
        @if (item.children?.length) {
          <li nz-submenu [nzTitle]="item.label" [nzDisabled]="item.disabled ?? false">
            <ul>
              @for (c of item.children!; track c.key) {
                <li nz-menu-item [nzSelected]="c.key === selectedKey()" [nzDisabled]="c.disabled ?? false" (click)="itemClick.emit(c)">{{ c.label }}</li>
              }
            </ul>
          </li>
        } @else {
          <li nz-menu-item [nzSelected]="item.key === selectedKey()" [nzDisabled]="item.disabled ?? false" (click)="itemClick.emit(item)">{{ item.label }}</li>
        }
      }
    </ul>
  `,
  host: { class: 'hrm-menu' },
})
export class HrmMenu {
  readonly items = input<HrmMenuItem[]>([]);
  readonly mode = input<'inline' | 'horizontal' | 'vertical'>('inline');
  readonly selectedKey = input<string>('');
  readonly collapsed = input(false);
  readonly itemClick = output<HrmMenuItem>();
}
